from flask import Flask, request, jsonify
from Bio import pairwise2
from Bio.Seq import Seq
import io
import warnings

warnings.filterwarnings("ignore")

app = Flask(__name__)

@app.route('/align', methods=['POST'])
def align_sequence():
    try:
        if 'file' not in request.files:
            return jsonify({'error': 'No file part'}), 400

        file = request.files['file']

        if file.filename == '':
            return jsonify({'error': 'No selected file'}), 400

        if file.type not in ['text/fasta']:
            return jsonify({'error': 'Invalid file type.  Must be FASTA'}), 400

        try:
            fasta_content = file.read().decode('utf-8')
            sequences = []
            for seq_record in pairwise2.parseSequences(fasta_content):
                sequences.append(str(seq_record[0]))

            if not sequences:
                return jsonify({'error': 'No sequences found in FASTA file'}), 400

            reference_sequence = 'ATCGATCGATCG'
            best_alignment = pairwise2.align.globalms(reference_sequence, sequences[0], 2, -10, -0.5)

            if not best_alignment:
                return jsonify({'alignment_score': 0, 'alignment': ''}), 200

            alignment_score = best_alignment[2]
            alignment = best_alignment[0]

            return jsonify({'alignment_score': alignment_score, 'alignment': alignment}), 200

        except Exception as e:
            return jsonify({'error': str(e)}), 500

    except Exception as e:
        return jsonify({'error': str(e)}), 500


if __name__ == '__main__':
    app.run(debug=True)
